int mylowerbound(const vector<node>& vec, long long n) {
  int start = 0, end = vec.size() - 1;
  if (n < vec[0].num) return 0;
  if (n > vec.back().num) return vec.size();
  while (start <= end) {
    if (start == end)
      return start;
    else if (start == end - 1) {
      if (vec[start].num >= n) return start;
      return end;
    } else {
      int mid = start + (end - start) / 2;
      if (vec[mid].num >= n)
        end = mid;
      else
        start = mid + 1;
    }
  }
  return -1;
}
