std::pair<int, int> dfs(int u, int fa = 0) {
	std::pair<int, int> res(0, u);
	for (int v : E[u]) {
		if (v != fa) {
			std::pair<int, int> tmp = dfs(v, u);
			++tmp.first;
			res = std::max(res, tmp);
		}
	}
	return res;
}

void getfa(int u) {
	for (int v : E[u]) {
		if (v != fa[u]) {
			fa[v] = u, getfa(v);
		}
	}
}

int f[N][N << 1];

void DP(int u, int fa, int d) {
	for (int i = -D; i <= D; ++i) {
		f[u][i + D] = -d <= i && i <= d;
	}
	for (int v : E[u]) {
		if (v != fa) {
			DP(v, u, d - 1);
			for (int i = 0; i <= 2 * D; ++i) {
				f[u][i] = 1ll * f[u][i] * ((i == 0 ? 0 : f[v][i - 1]) + (i == 2 * D ? 0 : f[v][i + 1])) % P;
			}
		}
	}
}

