int solve(int a, int b, int c=0) {
  a = min(a, sl);
  b = min(b, tl);
  // printf("%d %d %d\n", a, b, c);
  if (a >= sl - 1 && b >= tl - 1) return 0;
  if (dp[a][b] >= 0) return dp[a][b];
  int p = solve(nxs[a][0], nxt[b][0], 0) + 1;
  int q = solve(nxs[a][1], nxt[b][1], 1) + 1;
  if (p == q || p < q) nx[a][b] = 0;
  else nx[a][b] = 1;
  int res = min(p, q);
  return dp[a][b] = res;
}

void gen(char *s, int l, int nx[4444][2]) {
  for (int i = 0; i < l; i++) {
