      int k = i;
      if (s[k] == j + '0') nx[i][j] = k + 1;
      else {
        k += 1;
        while (s[k] && s[k] != j + '0') {
          ++k;
        }
        nx[i][j] = min(l, k + 1);
      }
    }
  }
  nx[l][0] = nx[l][1] = l;
}

