	return false;
}

void reduce(CONTAINER &m, size_t h, size_t w){
	for(size_t i = 0; i < 9; i++){
		m[h+dx[i]][w+dy[i]] -= 1;
	}
//	cerr << "pass" << endl;
}

bool isSwipe(const CONTAINER &m){
	for(auto a : m)for(auto e : a)
		if(e != 0)return false;
	return true;
}

