int solve()
{
	int ans = 0, count = 0;
	bool V[MAX_N];
    memset(V, false, sizeof(V));
    memcpy(B, A, sizeof(int) * n);
    sort(B, B + n);
    for (int i = 0; i < n; i++) T[B[i]] = i;
    for (int i = 0; i < n; i++) {
        if (V[i]) continue;
        int cur = i;
