bool vis[N];
set<int> unvis;

int p[N], p2[N], cnt[N], sz[N];

int root(int v){
  if(p[v] == v)
    return v;
  return p[v] = root(p[v]);
}

void merge(int a, int b){
  a = root(a);
  b = root(b);
  if(a == b)
    return;
  p[b] = a;
  sz[a] += sz[b];
}

int root2(int v){
  if(p2[v] == v)
    return v;
  return p2[v] = root2(p2[v]);
}

void merge2(int a, int b){
  a = root2(a);
  b = root2(b);
  if(a == b)
    return;
  p2[b] = a;
}

queue<int> q;
void bfs(int s){
  q.push(s);
  vis[s] = true;
  unvis.erase(s);
  while(!q.empty()){
    int v = q.front();
    q.pop();
    for(int x : g[v])
      if(!vis[x])
        unvis.erase(x);
    for(int x : unvis){
      merge(v, x);
      q.push(x);
      vis[x] = true;
    }
    unvis.clear();
    for(int x : g[v])
      if(!vis[x])
        unvis.insert(x);
  }
}

