    cin >> x >> y;
    if (mp[x][y]) {
      ans++;
      continue;
    }
    f[i] = i;
    f[i + c] = i + c;
    if (ck(x, y)) {
      ans++;
      alt(i, x, y);
      alt(i + c, x, y + m);
    }
  }
  cout << ans << endl;
}
