const ll N = 5e5 + 30, Mod = 1e9 + 7;
const ll SQ = 330;

ll n, k;
ll d[N];
ll a[N], q[N];
set<pll> s;
vector<ll> G[N];
void Add(ll v, ll u) {
	if (!~v || u > n) 
		return;
	G[v].pb(u);
	d[u] ++;
}
int main () {
    ios::sync_with_stdio(0), cin.tie(0);
   	cin >> n >> k;
   	s.insert({-1, -1});
   	s.insert({n + n, n + n});
