   		cin >> a[i];
		if (i > k)
			s.erase({a[i - k], i - k}); 
		auto it = *s.lower_bound({a[i], -1});
		ll x = it.S;
		Add(i, x);
		auto itt = s.lower_bound({a[i], -1});
		itt--;
		x = itt->S;
		Add(x, i);
		s.insert({a[i], i});
	}
	set<ll> Q;
	for (int i = 1; i <= n; i ++)
		if (!d[i])
			Q.insert(i);
	for (int i = 1; i <= n; i ++) {
