	for (int y = 0; y < R; y++)
		for (int x = 0; x < C; x++) {
			if (a[y][x] == '#') continue;
			for (int k = 0; k < 4; k++) {
				int _y = y + dy[k], _x = x + dx[k];
				if (_y >= 0 && _y < R && _x >= 0 && _x < C);
