bool check(const MSQ & temp, R r, const vector<P> &vil, int i, int j){
	MSQ msq;
	L l = temp.segment(j);
	P gp = vil[i] - l[0]*r;
	temp.copy(r, gp, msq);
	vector<P> p;
	P b(0), u = msq.segment(j)[1];
	if(u < b) swap(b, u);
	REP(i, n){
		S l2(vil[i], vil[i] + msq.segment(j).dir());
		int f = 0;
		P ll(INF, INF), rr(-INF, -INF);
		REP(j, m){
