using namespace std;
using i64 = int64_t;
using vi = vector<i64>;
using vvi = vector<vi>;

class SCCDecomp {
    int n;
    vvi adj;

public:
    vvi scc;
    SCCDecomp(int n) : n(n), adj(n) {}

    void addArc(int a, int b) {
        adj[a].push_back(b);
    }

    int run() {
        vi num(n), low(n);
        stack<int> S;
        vi inS(n);
        int t = 0;
        function<void(int)> visit = [&](int v) {
            low[v] = num[v] = ++t;
            S.push(v);
            inS[v] = 1;
            for (int s: adj[v]) {
                if (!num[s]) {
                    visit(s);
                    low[v] = min(low[v], low[s]);
                } else if (inS[s]) {
                    low[v] = min(low[v], num[s]);
                }
            }
            if (low[v] == num[v]) {
                scc.push_back(vi());
                while (1) {
                    int w = S.top();
                    S.pop();
                    inS[w] = false;
                    scc.back().push_back(w);
                    if (v == w) {
                        break;
                    }
                }
            }
        };

        for (int i = 0; i < n; i++) {
            if (num[i] == 0) {
                visit(i);
            }
        }

        return scc.size();
    }
};

int main() {
