  for (int i = 1; i < N; i++) {
    fac[i] = fac[i - 1] * i % MOD;
    ifac[i] = Inv(fac[i]);
  }
}
long long C(int n, int a) {
  if (n < 0 || a < 0 || n - a < 0)
    return 0;
  else
    return fac[n] * ifac[a] % MOD * ifac[n - a] % MOD;
}
