  int a = grr[0], b = grr[1], val = ask(a, b);
  for (int i = 2; i < n; i++) {
    int c = grr[i];
    int x = ask(b, c);
    if (x == val) {
      val = ask(a, c);
      b = c;
      continue;
    }
    if (val > x) {
      a = c;
      val = x;
    }
  }
  int nuller;
  for (int i = 1; i <= n; i++) {
    if (i == a || i == b) continue;
    int l = ask(a, i), r = ask(b, i);
    if (l == r) continue;
    if (l < r) {
      nuller = a;
      break;
    } else {
      nuller = b;
      break;
    }
  }
  vector<int> gr;
  gr.clear();
  for (int i = 1; i <= n; i++) {
    if (i == nuller) {
      gr.push_back(0);
      continue;
    }
    gr.push_back(ask(nuller, i));
  }
  cout << "! ";
  for (auto it : gr) cout << it << " ";
  cout << endl;
}
