	//If using nCr, then call precalc()
	ll n;
	cin >> n;
	vll vec(n);
	in(vec)
	vll left(n), right(n);
	stack<ll>s;
	s.push(0);

	forn(i, 1, n) {
		if (vec[i] < vec[s.top()]) {
			//o(i)
			while (!s.empty() && vec[s.top()] > vec[i])  {
				right[s.top()] = i;
				s.pop();
			}
		}
		s.push(i);
	}
	while (!s.empty()) {
		right[s.top()] = n;
		s.pop();
	}
	s.push(n - 1);
	revn(i, n - 2, 0) {
		if (vec[i] < vec[s.top()]) {
			//o(i)
			while (!s.empty() && vec[s.top()] > vec[i])  {
				left[s.top()] = i;
				s.pop();
			}
		}
		s.push(i);
	}
	while (!s.empty()) {
		left[s.top()] = -1;
		s.pop();
	}
	//out(left)
	map<ll, ll>hash;
	forn(i, 1, n + 1) {
		hash[i] = 0;
	}
	forn(i, 0, n) {
		hash[vec[i]] = max(hash[vec[i]], right[i] - left[i] - 1);
	}
	string ans = string(n, '0');
	vll suffix(n + 1);
	for (auto i : hash) {
		suffix[min(i.ss, n - i.ff + 1)]++;
	}
	revn(i, n - 1, 1) {
		suffix[i] += suffix[i + 1];
	}
	revn(i, n, 1) {
		if (hash[n + 1 - i] >= i && suffix[i] >= n + 1 - i) {
			ans[i - 1] = '1';
		}
	}
	o(ans)
}

