int solve(int l, int r, int colLeft, int colRight) {
  if (l > r) return 1;
  if (dp[l][r][colLeft][colRight] != -1) {
    return dp[l][r][colLeft][colRight];
  }
  int &temp = dp[l][r][colLeft][colRight];
  temp = 0;
