      ADD(0, maxn, 1, pos[A[i]] - i + 1, pos[A[i]] + 1, 1, 1);
      ADD(0, maxn, 1, pos[A[i]] + 1, n, n - i - 1, 0);
    } else {
      ADD(0, maxn, 1, 0, pos[A[i]] + 1, i - pos[A[i]], 1);
      ADD(0, maxn, 1, pos[A[i]] + 1, pos[A[i]] + n - i + 1, n - i - 1, 0);
      ADD(0, maxn, 1, n - i + pos[A[i]] + 1, n, 1, 1);
