double getR(double dist,double h){
  if(dist<h)return dist;
  double res = (dist*dist-h*h)/(2*h) + h;
  return res;
}
double notouchR(B b){
  const vector<L> bl = {
    L(P(b.x1,b.y1),P(b.x1,b.y2)),
    L(P(b.x1,b.y2),P(b.x2,b.y2)),
    L(P(b.x2,b.y2),P(b.x2,b.y1)),
