using namespace std;
typedef long long ll;

class UnionFind {
public:
	vector<ll> parent;
	vector<ll> gap;//強化前の、素の値
	vector<ll> up;//強化量

	UnionFind(ll n) : parent(n), gap(n, 0), up(n, 0) {
		REP(i, 0, n) parent[i] = i;
	}

	ll find(ll i) {
		if (parent[i] == i) return i;

		int tmp = parent[i];
		ll p = find(parent[i]);
		//cerr << "find  " << i+1 << " ,," << tmp+1 << "p: " << p+1 << endl;
		gap[i] += gap[tmp];
		return parent[i] = p;
	}

	void unite(ll i, ll j, ll c) {
		ll p = find(i), q = find(j);
		if (p != q) {
			gap[p] = c + get(j) - get(i);
			parent[p] = q;
		}
		up[i] += c;
		up[j] += c;
	}

	ll get(ll i) {
