	for (int i = 1; i <= N; i++) {
		for (int j = 0; j <= N; j++) {
			for (int k = 0; k <= W; k++) {
				dp[0][j][k] = dp[1][j][k];
				dp[1][j][k] = 0;
			}
		}
		int w = x[i];
