    }

    void set(int i,int x,int l,int r){
        int m=(l+r)/2;
        if(ch[0]==NULL)init();
        if(i<l || r<=i)return;
        if(x<value)value=x;
        if(r-l==1)return;
        ch[0]->set(i,x,l,m);
        ch[1]->set(i,x,m,r);
    }

    void set(int i,int x){
        set(i,x,0,segN);
    }

    int min(int a,int b,int l,int r){
        int m=(l+r)/2;
        if(ch[0]==NULL)init();
        if(b<=l || r<=a)return INF;
        if(a<=l && r<=b)return value;
        int lc=ch[0]->min(a,b,l,m);
        int rc=ch[1]->min(a,b,m,r);
        return (lc<rc?lc:rc);
    }

    int min(int a,int b){
        if(0<=a&&a<b)return min(a,b,0,segN);
        else return INF;
    }
};

int rak[MAX+1];
