    dp[b][a[1]][1] = 1;
  } else {
    for (int i = 1; i <= K; i++) {
      dp[b][i][1] = 1;
    }
  }
  for (int i = 1; i <= K; i++) {
    sum[b][i][1] = (dp[b][i][1] + sum[b][i - 1][1]) % mod;
    sum[b][i][0] = (dp[b][i][0] + sum[b][i - 1][0]) % mod;
  }
  b = 1;
