int c(int x,int y)
{
	if(x<y||x<0||y<0) return 0;
	return 1ll*fac[x]*fi[y]%mod*fi[x-y]%mod;
}
int pw(int x,int y)
{
	int z=1;
	while(y){
		if(y&1)z=1ll*z*x%mod;
		x=1ll*x*x%mod;y>>=1;
	}
	return z;
}
void ntt(int *a,int len,int op)
{
	int i,j,k;
	rep0(i,len){
		if(rev[i]<i){
			swap(a[i],a[rev[i]]);
		}
	}
	for(i=1;i<len;i<<=1){
		int stp=maxn/i/2;
		for(j=0;j<len;j+=i+i){
			int t=(op==1?0:maxn);
			rep0(k,i){
				int x=a[j+k],y=a[j+k+i]*1ll*w[t]%mod;
				a[j+k]=(x+y)%mod;a[j+k+i]=(x-y+mod)%mod;
				t+=stp*op;
			}
		}
	}
	if(op==-1){
		rep0(i,len) a[i]=1ll*a[i]*inv[len]%mod;
	}
}
int getrev(int x)
{
	int len=1,i;
	while(len<=x)len<<=1;
	rep0(i,len){
		rev[i]=(rev[i/2]/2)+((i&1)*(len/2));
	}
	return len;
}
