  long long Dot(Point rhs) { return 1LL * x * rhs.x + 1LL * y * rhs.y; }
  long long Crs(Point rhs) { return 1LL * x * rhs.y - 1LL * y * rhs.x; }
};
bool operator<(Point lhs, Point rhs) {
  return (lhs.x == rhs.x) ? (lhs.y < rhs.y) : (lhs.x < rhs.x);
}
