double Stat(int* e, int Min, int Max) {
  double ret = 0;
  double Count = 0, sumPlain = 0, sumSquare = 0;
  int i;
  for (i = Min; i <= Max; i++) {
    ret += e[i] * (Count * i * i + sumSquare - 2.0 * i * sumPlain);
    Count += e[i];
    sumPlain += e[i] * 1.0 * i;
    sumSquare += e[i] * 1.0 * i * i;
  }
  return ret;
}
