  for (i = ml + 1; i <= N; i++) {
    while ((H[0].size() > 1) &&
           ((H[0].back() - H[0][H[0].size() - 2]).Crs(p[i] - H[0].back()) <= 0))
      H[0].pop_back();
    while ((H[1].size() > 1) &&
           ((H[1].back() - H[1][H[1].size() - 2]).Crs(p[i] - H[1].back()) >= 0))
      H[1].pop_back();
    H[0].push_back(p[i]);
    H[1].push_back(p[i]);
  }
  while ((H[0].size() > 1) && (H[0].back().x == H[0][H[0].size() - 2].x))
    H[0].pop_back();
