  }
  void init(string e) {
    e = e + "$";
    s = e;
    n = s.length();
    for (int i = (0); i < (n); i++) {
      SA[i] = i;
      RA[i] = s[i];
    }
    for (int k = 1; k <= n; k *= 2) {
      countingsort(k);
      countingsort(0);
      for (int j = (0); j < (n); j++) {
        int i = SA[j];
        if (j == 0) {
          tempRA[i] = 0;
          continue;
        }
        int p = SA[j - 1];
        if (RA[i] == RA[p] && RA[i + k] == RA[p + k]) {
          tempRA[i] = tempRA[p];
