long long binpow(long long a, long long b) {
  long long res = 1;
  while (b) {
    if (b & 1) {
      res *= a, res %= Mod;
      b--;
    }
    a *= a;
    a %= Mod;
    b >>= 1;
  }
  return res;
}
long long C(long long x, long long y) {
  long long res = f[x + y - 1];
  res *= binpow(f[x], Mod - 2);
  res %= Mod;
  res *= binpow(f[y - 1], Mod - 2);
  res %= Mod;
  return res;
}
