  if (vis[node] != 0) {
    if (vis[node] == curr) {
      parent[node] = node;
      roots.push_back(node);
    } else {
      return;
    }
  }
  vis[node] = curr;
  if (node != parent[node]) {
    dfs(parent[node]);
  }
}
