class Treap {
 public:
  typedef struct _node {
    long long key;
    long long cnt;
    long long prior;
    long long val[2];
    _node* l;
    _node* r;
    _node(long long key) : key(key), l(nullptr), r(nullptr), cnt(1) {
      prior = (rand() << 16) | rand();
      val[0] = (key + 1);
      val[1] = (key + 1);
    }
    void push() {}
    void recalc() {
      cnt = 1 + Cnt(l) + Cnt(r);
