        val[w] = powers[w][Cnt(r)] * (key + 1) % mods[w];
        if (l) {
          val[w] += powers[w][Cnt(r) + 1] * l->val[w];
        }
        if (r) {
          val[w] += r->val[w];
        }
        val[w] %= mods[w];
      }
    }
    long long get_hash() { return (val[0] * 1LL << 32) | val[1]; }
    static long long Cnt(_node* v) {
      if (!v) return 0;
      return v->cnt;
    }
  } * node;
  static long long Cnt(node v) {
    if (!v) return 0;
    return v->cnt;
  }
  node root;
  size_t Size;
  node merge(node l, node r) {
    if (!l) return r;
    if (!r) return l;
    if (l->prior < r->prior) {
      l->push();
      l->r = merge(l->r, r);
      l->recalc();
      return l;
    } else {
      r->push();
      r->l = merge(l, r->l);
      r->recalc();
      return r;
    }
  }
  void split(node v, long long key, node& l, node& r) {
    l = r = nullptr;
    if (!v) return;
    v->push();
    if (v->key < key) {
      l = v;
      split(l->r, key, l->r, r);
      l->recalc();
    } else {
      r = v;
      split(r->l, key, l, r->l);
      r->recalc();
    }
  }
  void splitCnt(node v, long long key, node& l, node& r) {
    l = r = nullptr;
    if (!v) return;
    v->push();
    long long lef = Cnt(v->l) + 1;
    if (key >= lef) {
      l = v;
      splitCnt(l->r, key - lef, l->r, r);
      l->recalc();
    } else {
      r = v;
      splitCnt(r->l, key, l, r->l);
      r->recalc();
    }
  }

 public:
  Treap() {
    root = nullptr;
    Size = 0;
  }
  size_t size() const { return Size; }
  void insert(long long key) {
    node l = nullptr, r = nullptr;
    split(root, key, l, r);
    ++Size;
    root = merge(merge(l, new _node(key)), r);
  }
  void erase(long long key) {
    node l, m, r;
    split(root, key, l, m);
    splitCnt(m, 1, m, r);
    root = merge(l, r);
    --Size;
  }
  long long get_hash() {
    if (!root) {
      return 0;
    }
    return root->get_hash();
  }
};
