void doit(long long v) {
  used[v] = 1;
  for (auto i : g[v]) {
    if (!used[i.first]) {
      p[i.first] = v;
      doit(i.first);
      ans[i.second] = c[i.first] - dp[i.first];
      dp[i.first] += ans[i.second];
      dp[v] += ans[i.second];
